import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return an empty grid for a single live cell with no neighbors");
  it.todo("should return an empty grid for two adjacent cells that each have one neighbor");
  it.todo("should keep a live cell with three live neighbors alive");
  it.todo("should kill a live cell with four live neighbors");
  it.todo("should bring a dead cell with exactly three live neighbors to life");
  it.todo("should turn a vertical blinker into a horizontal blinker");
  it.todo("should turn a horizontal blinker back into a vertical blinker");
  it.todo("should leave a block unchanged");
  it.todo("should compute the next generation for cells at negative coordinates");
});
